import re
p='src/CheckoutPricing.Application/'
s=open(p+'CalculateLoyaltyDiscount.cs').read()
s=re.sub(r'public LoyaltyDiscountQuote Handle.*?;\n',
'''public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discount = DiscountPolicy.DiscountCents(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
        return new(query.SubtotalCents, discount, query.SubtotalCents - discount, query.LoyaltyTier);
    }
''',s,flags=re.S)
open(p+'CalculateLoyaltyDiscount.cs','w').write(s)
s=open(p+'CalculateShippingFee.cs').read()
s=s.replace('Handle(CalculateShippingFeeQuery query) => 0;','Handle(CalculateShippingFeeQuery query) =>\n        ShippingPolicy.FeeCents(query.PayableTotalCents, query.LoyaltyTier, query.Express);')
open(p+'CalculateShippingFee.cs','w').write(s)
s=open(p+'QuoteCheckout.cs').read()
s=s.replace('CheckoutQuote Handle(QuoteCheckoutQuery query) => new(0, 0, 0);','''CheckoutQuote Handle(QuoteCheckoutQuery query)
    {
        var payable = query.SubtotalCents
            - DiscountPolicy.DiscountCents(query.SubtotalCents, query.LoyaltyTier, query.PromoCode);
        var shipping = ShippingPolicy.FeeCents(payable, query.LoyaltyTier, query.Express);
        return new(payable, shipping, payable + shipping);
    }''')
open(p+'QuoteCheckout.cs','w').write(s)
E
