+namespace CheckoutPricing.Domain;
+
+public static class DiscountPolicy
+{
+    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
+    {
+        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPartCents(subtotalCents, tier);
+        var promoPart = PromoCodePolicy.PromoPartCents(promoCode, subtotalCents - loyaltyPart);
+        return Math.Min(loyaltyPart + promoPart, subtotalCents);
+    }
+}

