using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Domain;

public sealed class LoyaltyDiscountPolicyTests
{
    [Theory]
    [InlineData(3_000, LoyaltyTier.Bronze, 150)]
    [InlineData(3_001, LoyaltyTier.Silver, 300)]
    [InlineData(3_007, LoyaltyTier.Gold, 451)]
    [InlineData(3_001, LoyaltyTier.Platinum, 600)]
