    [InlineData(1, LoyaltyTier.Gold, 0)]
    [InlineData(7, LoyaltyTier.Platinum, 0)]
    public void LoyaltyPartRoundsDownToTheCent(int subtotalCents, LoyaltyTier tier, int expectedCents) =>
        Assert.Equal(expectedCents, LoyaltyDiscountPolicy.LoyaltyPartCents(subtotalCents, tier));
}

